window.KIT={"days": [{"t": "Studio & e-commerce content", "wk": 1, "w": [["Easy", "photo shoot", "n", "buổi chụp ảnh", "The photo shoot for the summer collection starts on Monday.", "Chung"], ["Easy", "deadline", "n", "hạn chót", "Can we still meet the deadline if the model changes?", "Chung"], ["Easy", "sample", "n", "hàng mẫu (sản phẩm gửi tới studio để chụp)", "Each sample is scanned when it arrives at the studio.", "Chung"], ["Easy", "deliver", "v", "bàn giao, giao (sản phẩm, kết quả)", "We deliver the final images straight to the client's website.", "Chung"], ["Medium", "turnaround time", "n", "thời gian xử lý trọn vòng (từ lúc nhận đến lúc xong)", "Our goal is to cut turnaround time from days to hours.", "Chung"], ["Medium", "retouch", "v/n", "chỉnh sửa ảnh hậu kỳ", "The retouch team removes dust and wrinkles from the garment.", "Chung"], ["Medium", "style guide", "n", "bộ quy chuẩn hình ảnh của thương hiệu", "Every image must follow the brand's style guide: angle, crop and background.", "Chung"], ["Medium", "packshot", "n", "ảnh sản phẩm trên nền trơn", "A packshot shows the product alone on a white background.", "Chung"], ["Hard", "in-stock not live", "phrase", "hàng đã có trong kho nhưng chưa lên web bán", "Customers care most about reducing the in-stock-not-live time.", "Chung"], ["Hard", "throughput", "n", "năng suất / lượng xử lý được trong một khoảng thời gian", "We need higher throughput without hiring more photographers.", "Chung"], ["Easy", "image-to-video", "n", "tạo video từ ảnh", "Image-to-video turns one product photo into a short clip.", "Sản phẩm"], ["Medium", "product tagging", "n", "gắn thẻ thuộc tính sản phẩm tự động", "Product tagging fills in colour, sleeve length and material.", "Sản phẩm"], ["Hard", "label recognition", "n", "đọc nhãn mác sản phẩm bằng AI", "Label recognition reads the care label at sample check-in.", "Sản phẩm"]], "s": ["Good morning, everyone.", "Quick context before we start.", "Our customers run large photo studios, and every sample that arrives has to be shot, retouched and delivered before the deadline.", "The metric they care about most is in-stock not live: how long a product sits in the warehouse before it can be sold online.", "If we can cut turnaround time and raise throughput, that is real money for them."], "sp": "Giới thiệu với PM bạn hiểu Creative Force giải quyết vấn đề gì cho studio, và vì sao 'turnaround time' quan trọng."}, {"t": "Workflow & assets", "wk": 1, "w": [["Easy", "workflow", "n", "quy trình làm việc", "Shoes and bags follow different workflows.", "Chung"], ["Easy", "task", "n", "đầu việc, nhiệm vụ", "The task moves to QC once the retouch is done.", "Chung"], ["Easy", "step", "n", "bước", "Which step takes the longest right now?", "Chung"], ["Easy", "approve", "v", "phê duyệt", "The art director approves the final selection.", "Chung"], ["Medium", "bottleneck", "n", "điểm nghẽn", "Retouching is the bottleneck this week.", "Chung"], ["Medium", "asset", "n", "tài sản số (ảnh, video, file)", "Each product usually has six to eight assets.", "Chung"], ["Medium", "metadata", "n", "siêu dữ liệu (thông tin đi kèm file)", "We attach metadata such as colour and SKU to every file.", "Chung"], ["Medium", "SKU", "n", "mã hàng (stock keeping unit)", "One style can have several SKUs, one for each colour.", "Chung"], ["Hard", "DAM (digital asset management)", "n", "hệ thống quản lý tài sản số", "Finished assets are pushed to the client's DAM automatically.", "Chung"], ["Hard", "flow production", "n", "sản xuất dạng dòng chảy: xong bước nào chuyển ngay bước đó", "With flow production, an image moves on as soon as its task is finished.", "Chung"], ["Easy", "integrate", "v", "tích hợp", "We integrate the QC model into the existing workflow.", "JD"], ["Medium", "API integration", "n", "tích hợp qua API", "Most enterprise customers need an API integration with their DAM.", "Sản phẩm"], ["Hard", "business domain", "n", "lĩnh vực nghiệp vụ", "Learn the business domain before proposing AI features.", "JD"]], "s": ["Let me walk you through the workflow.", "A product is checked in, photographed, retouched and approved, and every step is a task in the system.", "Each asset carries metadata, like the SKU and the colour, so it ends up in the right place in the customer's DAM.", "Right now the bottleneck is retouching, so that's where we think AI can help first."], "sp": "Mô tả lại workflow của một sản phẩm từ lúc check-in đến lúc giao, và đề xuất một bước mà AI có thể giúp."}, {"t": "Customers & business", "wk": 1, "w": [["Easy", "customer", "n", "khách hàng", "The customer asked for a faster export to their website.", "Chung"], ["Easy", "brand", "n", "thương hiệu", "Each brand has its own look and rules.", "Chung"], ["Easy", "retailer", "n", "nhà bán lẻ", "Large retailers shoot thousands of products every week.", "Chung"], ["Easy", "feature", "n", "tính năng", "This feature was requested by three customers.", "Chung"], ["Medium", "e-commerce", "n", "thương mại điện tử", "E-commerce teams need images for many channels at once.", "Chung"], ["Medium", "stakeholder", "n", "bên liên quan", "Let's share the results with the stakeholders on Friday.", "Chung"], ["Medium", "onboarding", "n", "quá trình tiếp nhận, làm quen (khách hàng / nhân viên mới)", "Onboarding a new studio takes about two weeks.", "Chung"], ["Medium", "churn", "n/v", "khách hàng rời bỏ dịch vụ", "Good support keeps churn low.", "Chung"], ["Hard", "SaaS (software as a service)", "n", "phần mềm dạng dịch vụ (thuê bao)", "As a SaaS company, we ship improvements every sprint.", "Chung"], ["Hard", "enterprise customer", "n", "khách hàng doanh nghiệp lớn", "Enterprise customers often ask for single sign-on and custom reports.", "Chung"], ["Easy", "personalise", "v", "cá nhân hoá", "We personalise answers using the user's profile.", "CV"], ["Medium", "recommendation system", "n", "hệ thống gợi ý", "I built a recommendation system for pharma content.", "CV"], ["Hard", "next-best-action", "n", "gợi ý hành động tốt nhất tiếp theo", "The next-best-action model chose the channel and the content.", "CV"]], "s": ["Most of our customers are brands and retailers with big e-commerce operations.", "For an enterprise customer, a new feature is only useful if onboarding is easy and it fits their existing tools.", "When a feature saves them time, churn goes down, so the business side is very interested in anything AI can automate."], "sp": "Đóng vai giải thích cho PM: tính năng AI nào bạn nghĩ sẽ giảm churn và vì sao."}, {"t": "Dreem & generative content", "wk": 1, "w": [["Easy", "generate", "v", "tạo ra (bằng AI)", "The model generates four images in about a minute.", "Chung"], ["Easy", "background", "n", "phông nền", "Please keep the background plain white.", "Chung"], ["Easy", "pose", "n", "tư thế", "Can we get the same outfit in three different poses?", "Chung"], ["Easy", "outfit", "n", "bộ trang phục", "The outfit builder combines a top, trousers and shoes.", "Chung"], ["Medium", "virtual model", "n", "người mẫu ảo do AI tạo", "Virtual models let brands show products before the samples arrive.", "Chung"], ["Medium", "flat-lay", "n", "ảnh sản phẩm trải phẳng", "We start from a flat-lay and generate an on-model image.", "Chung"], ["Medium", "on-model image", "n", "ảnh có người mẫu mặc sản phẩm", "On-model images usually convert better than packshots.", "Chung"], ["Medium", "variation", "n", "biến thể", "Generate five variations and let the art director pick one.", "Chung"], ["Hard", "garment fidelity", "n", "độ trung thực của trang phục (giữ đúng màu, logo, chi tiết)", "Garment fidelity matters more than a pretty face: the logo must stay exact.", "Chung"], ["Hard", "brand compliance", "n", "tuân thủ quy chuẩn thương hiệu", "Every generated image goes through a brand compliance check.", "Chung"], ["Easy", "copywriting", "n", "viết nội dung quảng cáo/mô tả sản phẩm", "The AI copywriter drafts product descriptions.", "Sản phẩm"], ["Medium", "colour variation", "n", "biến thể màu", "Generate colour variations instead of shooting every colour.", "Sản phẩm"], ["Hard", "photorealistic", "adj", "chân thực như ảnh chụp", "The output must be photorealistic, not illustrated.", "Sản phẩm"]], "s": ["With Dreem, a customer uploads a flat-lay and we generate an on-model image with a virtual model.", "They can ask for different poses, a new background or a few variations.", "The hard part is garment fidelity: the colour, the logo and the fabric must look exactly like the real product, otherwise the image fails brand compliance."], "sp": "Giải thích cho PM cách bạn sẽ kiểm tra 'garment fidelity' của ảnh AI tạo ra."}, {"t": "Meeting basics", "wk": 1, "w": [["Easy", "agenda", "n", "chương trình họp", "Let's go through the agenda first.", "Chung"], ["Easy", "update", "n", "cập nhật tình hình", "Can you give us a quick update on the model?", "Chung"], ["Easy", "follow up", "phr v", "theo dõi tiếp, hỏi lại sau", "I'll follow up with the backend team today.", "Chung"], ["Easy", "action item", "n", "đầu việc cần làm sau cuộc họp", "Let's end with the action items and owners.", "Chung"], ["Medium", "stand-up", "n", "buổi họp ngắn hằng ngày", "In stand-up, keep it to yesterday, today and blockers.", "Chung"], ["Medium", "blocker", "n", "vấn đề cản trở công việc", "Is anything blocking you? Any blockers?", "Chung"], ["Medium", "sync", "n/v", "họp nhanh để thống nhất thông tin", "Let's do a quick sync after lunch.", "Chung"], ["Medium", "recap", "n/v", "tóm tắt lại", "Quick recap: we ship the QC model next week.", "Chung"], ["Hard", "circle back", "phr v", "quay lại bàn sau", "Let's circle back to pricing on Thursday.", "Chung"], ["Hard", "park (an idea)", "v", "tạm gác lại một ý", "Good point, but let's park it for now.", "Chung"], ["Easy", "code review", "n", "rà soát mã", "Can you do a code review before lunch?", "JD"], ["Medium", "pull request (PR)", "n", "yêu cầu gộp mã", "I've opened a pull request for the new endpoint.", "JD"], ["Hard", "merge conflict", "n", "xung đột khi gộp mã", "I'll fix the merge conflict and push again.", "JD"]], "s": ["Okay, let's keep this short.", "I'll go through the agenda, then everyone gives a quick update.", "If you have a blocker, say it now, and we can sync afterwards.", "The pricing question is important, but let's park it and circle back on Thursday.", "At the end I'll do a recap and we'll agree on the action items."], "sp": "Mô phỏng một buổi stand-up: bạn báo cáo hôm qua làm gì, hôm nay làm gì, có blocker gì."}, {"t": "Clarifying & agreeing", "wk": 1, "w": [["Easy", "confirm", "v", "xác nhận", "Just to confirm, the deadline is Friday?", "Chung"], ["Easy", "clarify", "v", "làm rõ", "Could you clarify what 'done' means here?", "Chung"], ["Easy", "suggest", "v", "đề xuất", "I suggest we test it with one studio first.", "Chung"], ["Easy", "agree", "v", "đồng ý", "I agree with the plan, with one small change.", "Chung"], ["Medium", "align on", "phr v", "thống nhất về", "Let's align on the success metric before we build.", "Chung"], ["Medium", "on the same page", "idiom", "hiểu giống nhau, thống nhất", "I want to make sure we're on the same page about scope.", "Chung"], ["Medium", "rephrase", "v", "nói lại theo cách khác", "Sorry, let me rephrase the question.", "Chung"], ["Medium", "assumption", "n", "giả định", "My assumption is that most images are on white backgrounds.", "Chung"], ["Hard", "push back", "phr v", "phản bác, không đồng ý (có lý do)", "Feel free to push back if the timeline is unrealistic.", "Chung"], ["Hard", "trade-off", "n", "sự đánh đổi", "The trade-off is quality versus speed.", "Chung"], ["Easy", "requirement", "n", "yêu cầu", "Let's write down the requirements first.", "JD"], ["Medium", "use case", "n", "tình huống sử dụng", "The main use case is studios with thousands of SKUs.", "JD"], ["Hard", "non-functional requirement", "n", "yêu cầu phi chức năng (tốc độ, bảo mật...)", "Latency under five seconds is a non-functional requirement.", "JD"]], "s": ["Before we start building, I want to make sure we're on the same page.", "Can you clarify your assumption about the input images?", "If you think the timeline is too tight, please push back now, not in two weeks.", "There is always a trade-off between quality and speed, so let's align on which one matters more for this release."], "sp": "Luyện hỏi lại và xác nhận: PM giao việc mơ hồ, bạn hỏi để làm rõ phạm vi, giả định và deadline."}, {"t": "Words from the Creative Force intro video", "wk": 1, "w": [["Easy", "check in", "phr v", "ghi nhận (mẫu) vào studio", "Samples are checked in with a barcode scanner.", "Chung"], ["Easy", "freelancer", "n", "người làm tự do", "Freelancers can learn the system in a few hours.", "Chung"], ["Easy", "report", "n", "báo cáo", "The report shows turnaround time per studio.", "Chung"], ["Easy", "lead", "n", "trưởng nhóm", "The studio lead decides who retouches which images.", "Chung"], ["Medium", "naming convention", "n", "quy ước đặt tên file", "The system renames every file to match the naming convention.", "Chung"], ["Medium", "kanban board", "n", "bảng kanban theo dõi công việc", "You can see the bottleneck immediately on the kanban board.", "Chung"], ["Medium", "load balancing", "n", "cân bằng tải", "Load balancing moves work to whoever has free capacity.", "Chung"], ["Medium", "rejection rate", "n", "tỉ lệ bị trả lại / không đạt", "Which retouching service has the lowest rejection rate?", "Chung"], ["Hard", "reroute", "v", "chuyển hướng (công việc) sang nơi khác", "A studio lead can reroute images to an external retoucher.", "Chung"], ["Hard", "end-to-end", "adj", "từ đầu đến cuối, trọn vẹn", "Creative Force is end-to-end production management.", "Chung"], ["Easy", "mentor", "v/n", "kèm cặp / người kèm cặp", "I mentored two junior data scientists.", "JD/CV"], ["Medium", "pair programming", "n", "lập trình theo cặp", "We use pair programming to onboard new engineers.", "JD"], ["Hard", "knowledge transfer", "n", "chuyển giao kiến thức", "Let's plan a knowledge transfer before you go on holiday.", "JD"]], "s": ["Creative Force is end-to-end production management.", "Samples are checked in, and every file follows the naming convention automatically.", "On the kanban board a studio lead can see where images are stacking up, and with load balancing they can reroute work to an external service.", "The reports even show the rejection rate of each retouching partner."], "sp": "Ôn tuần 1: tóm tắt cho PM bằng 2 phút sản phẩm Creative Force làm gì, dùng ít nhất 10 từ của tuần."}, {"t": "LLM basics", "wk": 2, "w": [["Easy", "model", "n", "mô hình", "Which model are we using in production?", "Chung"], ["Easy", "prompt", "n/v", "câu lệnh / chỉ dẫn cho mô hình", "A clearer prompt fixed most of the errors.", "Chung"], ["Easy", "output", "n", "kết quả đầu ra", "The output must be valid JSON.", "Chung"], ["Easy", "token", "n", "đơn vị văn bản mô hình xử lý", "Long product descriptions use a lot of tokens.", "Chung"], ["Medium", "context window", "n", "độ dài ngữ cảnh tối đa mô hình đọc được", "The whole style guide fits in the context window.", "Chung"], ["Medium", "hallucination", "n", "mô hình bịa ra thông tin sai", "We saw hallucinations in the product attributes.", "Chung"], ["Medium", "temperature", "n", "tham số điều chỉnh độ ngẫu nhiên", "Set the temperature to zero for tagging.", "Chung"], ["Medium", "structured output", "n", "đầu ra có cấu trúc (theo schema)", "We use structured output so the code can parse the answer.", "Chung"], ["Hard", "grounding", "n", "neo câu trả lời vào dữ liệu thật", "Grounding the answer in the product data reduces hallucinations.", "Chung"], ["Hard", "inference", "n", "quá trình chạy mô hình để ra kết quả", "Inference cost is now our biggest AI expense.", "Chung"], ["Easy", "chatbot", "n", "trợ lý chat", "The chatbot answers questions about the style guide.", "CV"], ["Medium", "prompt engineering", "n", "kỹ thuật viết prompt", "Prompt engineering fixed most Japanese queries.", "CV"], ["Hard", "reasoning", "n", "khả năng suy luận", "Reasoning models are slower but better at multi-step tasks.", "JD"]], "s": ["For product tagging we send the image and a short prompt, and the model returns structured output, so the code can parse it safely.", "We keep the temperature at zero.", "The main risk is hallucination: the model invents a material that isn't there.", "Grounding the answer in the product data helps, and it also reduces the number of tokens per request."], "sp": "Giải thích cho PM (không chuyên kỹ thuật) hallucination là gì và bạn giảm nó bằng cách nào."}, {"t": "RAG", "wk": 2, "w": [["Easy", "search", "v/n", "tìm kiếm", "Users search the catalogue in plain language.", "Chung"], ["Easy", "document", "n", "tài liệu", "We indexed every style guide document.", "Chung"], ["Easy", "query", "n", "câu truy vấn", "The query was 'red summer dress under 100 euros'.", "Chung"], ["Easy", "chunk", "n/v", "đoạn nhỏ / chia nhỏ văn bản", "We split long documents into chunks of about 500 tokens.", "Chung"], ["Medium", "embedding", "n", "vector biểu diễn ý nghĩa", "We store an embedding for each product image.", "Chung"], ["Medium", "vector database", "n", "cơ sở dữ liệu vector", "The vector database returns the closest products in milliseconds.", "Chung"], ["Medium", "retrieval", "n", "bước truy xuất dữ liệu liên quan", "Most bad answers came from bad retrieval, not from the model.", "Chung"], ["Medium", "rerank", "v", "sắp xếp lại kết quả theo độ liên quan", "We rerank the top twenty results before answering.", "Chung"], ["Hard", "recall", "n", "độ bao phủ (tỉ lệ tìm được kết quả đúng)", "Recall at ten went from 70 to 85 percent.", "Chung"], ["Hard", "metadata filtering", "n", "lọc theo metadata ngay trong tìm kiếm vector", "Metadata filtering keeps out products from other brands.", "Chung"], ["Easy", "index", "n/v", "chỉ mục / lập chỉ mục", "We index new documents every night.", "CV"], ["Medium", "ingestion", "n", "nạp dữ liệu vào hệ thống", "The ingestion pipeline handles PDFs and URLs.", "CV"], ["Hard", "hybrid search", "n", "tìm kiếm kết hợp từ khoá và vector", "Hybrid search finds exact SKUs and similar styles.", "CV"]], "s": ["When answers were wrong, we checked retrieval first.", "We split each document into chunks, created an embedding for each chunk and stored them in a vector database.", "Then we added metadata filtering, so a query only searches the right brand, and a small reranker on the top results.", "Recall at ten went up by about fifteen points."], "sp": "Giải thích pipeline RAG bạn từng làm (Executive Assistant) trong 3 phút, PM sẽ hỏi lại."}, {"t": "Agents", "wk": 2, "w": [["Easy", "tool", "n", "công cụ (hàm mà agent gọi được)", "The agent has three tools: search, generate and check.", "Chung"], ["Easy", "memory", "n", "bộ nhớ", "Long-term memory remembers the user's preferences.", "Chung"], ["Easy", "route", "v", "định tuyến, chuyển hướng", "The router sends each message to the right branch.", "Chung"], ["Easy", "loop", "n", "vòng lặp", "The QC loop retries once, then asks a human.", "Chung"], ["Medium", "agent", "n", "tác tử AI tự quyết định các bước", "An agent decides which tool to call next.", "Chung"], ["Medium", "tool calling", "n", "việc mô hình gọi hàm/công cụ", "Tool calling lets the model fetch live product data.", "Chung"], ["Medium", "orchestration", "n", "điều phối các bước/agent", "We use LangGraph for orchestration.", "Chung"], ["Medium", "state", "n", "trạng thái", "The graph state keeps the photo, the product and the scores.", "Chung"], ["Hard", "guardrail", "n", "cơ chế chặn an toàn", "A guardrail rejects photos with more than one person.", "Chung"], ["Hard", "human-in-the-loop", "adj", "có con người tham gia kiểm duyệt", "Low-scoring images go through a human-in-the-loop review.", "Chung"], ["Easy", "planning", "n", "lập kế hoạch (của agent)", "The agent starts with planning, then calls tools.", "JD"], ["Medium", "multi-agent system", "n", "hệ nhiều agent phối hợp", "Our interview platform was a multi-agent system with three rounds.", "JD/CV"], ["Hard", "MCP (Model Context Protocol)", "n", "giao thức chuẩn để kết nối mô hình với công cụ/dữ liệu", "We could expose the catalogue as an MCP server.", "JD"]], "s": ["The agent is deliberately simple.", "A router reads the message and routes it to one of three branches.", "The try-on branch is a loop: a guardrail checks the photo, a tool generates the image, and a judge scores it.", "If it fails twice, it becomes a human-in-the-loop task.", "The graph state keeps everything, so we can replay any run."], "sp": "Trả lời câu hỏi của PM: 'Khi nào nên dùng agent, khi nào chỉ cần một prompt?'"}, {"t": "AI evaluation", "wk": 2, "w": [["Easy", "test", "v/n", "kiểm thử", "We test every prompt change before release.", "Chung"], ["Easy", "score", "n", "điểm số", "The average score was 7.8 out of 10.", "Chung"], ["Easy", "accuracy", "n", "độ chính xác", "Tagging accuracy is now 92 percent.", "Chung"], ["Easy", "result", "n", "kết quả", "I'll share the results in the channel.", "Chung"], ["Medium", "benchmark", "n", "bài đánh giá chuẩn để so sánh", "We built our own benchmark of 200 product images.", "Chung"], ["Medium", "ground truth", "n", "đáp án chuẩn (do người gán)", "Two retouchers labelled the ground truth.", "Chung"], ["Medium", "golden dataset", "n", "bộ dữ liệu chuẩn dùng để đánh giá lại liên tục", "Every release runs against the golden dataset.", "Chung"], ["Medium", "LLM-as-a-judge", "n", "dùng mô hình ngôn ngữ để chấm điểm", "We use LLM-as-a-judge, but we check it against humans.", "Chung"], ["Hard", "calibrate", "v", "hiệu chỉnh (cho khớp với chuẩn)", "We need to calibrate the judge before we trust its numbers.", "Chung"], ["Hard", "regression", "n", "sự thụt lùi chất lượng sau một thay đổi", "The eval caught a regression in colour accuracy.", "Chung"], ["Easy", "metric", "n", "chỉ số đo", "Which metric do we report to the customer?", "JD"], ["Medium", "precision", "n", "độ chính xác của các kết quả trả về", "High precision means few false alarms.", "JD"], ["Hard", "inter-annotator agreement", "n", "mức đồng thuận giữa những người gán nhãn", "Inter-annotator agreement was only 80 percent.", "CV"]], "s": ["How do we know the new model is better?", "We built a golden dataset of two hundred images with ground truth from our retouchers.", "Every change runs against it, and the eval caught a regression last week.", "We also use an LLM-as-a-judge, but first we calibrate it against human scores, because a judge that gives everything a nine is useless."], "sp": "PM hỏi: 'Làm sao em biết model mới tốt hơn model cũ?' — trả lời có số liệu và quy trình."}, {"t": "Latency & performance", "wk": 2, "w": [["Easy", "response", "n", "phản hồi", "The response should start in under two seconds.", "Chung"], ["Easy", "request", "n", "yêu cầu (gửi tới API)", "Each request includes one image.", "Chung"], ["Easy", "timeout", "n", "hết thời gian chờ", "We hit a timeout when the GPU was busy.", "Chung"], ["Easy", "cache", "n/v", "bộ nhớ đệm / lưu đệm", "We cache results by image hash.", "Chung"], ["Medium", "latency", "n", "độ trễ", "Latency doubled after the last release.", "Chung"], ["Medium", "time to first token (TTFT)", "n", "thời gian đến khi có chữ đầu tiên", "We cut time to first token from ten seconds to three.", "Chung"], ["Medium", "streaming", "n", "trả kết quả dần dần theo luồng", "Streaming makes the answer feel much faster.", "Chung"], ["Medium", "in parallel", "phrase", "song song", "We run both searches in parallel.", "Chung"], ["Hard", "p95 latency", "n", "độ trễ phân vị 95 (95% request nhanh hơn mức này)", "Average latency is fine, but p95 latency is eight seconds.", "Chung"], ["Hard", "critical path", "n", "đường găng: chuỗi bước quyết định tổng thời gian", "We moved memory writes off the critical path.", "Chung"], ["Easy", "profile", "v", "đo đạc hiệu năng từng phần", "I profiled every node to find the slow call.", "CV"], ["Medium", "asynchronous (async)", "adj", "bất đồng bộ", "The memory write is asynchronous.", "JD"], ["Hard", "high availability (HA)", "n", "tính sẵn sàng cao", "High availability means no single GPU can take us down.", "JD"]], "s": ["The average looks fine, but p95 latency is almost eight seconds, and users notice that.", "I profiled every step.", "Two calls were running one after the other, so now they run in parallel.", "Memory writes are off the critical path, and we cache results by image hash.", "With streaming, time to first token is now under three seconds."], "sp": "Kể lại câu chuyện tối ưu TTFT 9,9 s → 3 s cho PM, nhấn mạnh tác động tới người dùng."}, {"t": "Cost", "wk": 2, "w": [["Easy", "cost", "n", "chi phí", "What is the cost per thousand images?", "Chung"], ["Easy", "budget", "n", "ngân sách", "We have a monthly budget for GPU time.", "Chung"], ["Easy", "price", "n/v", "giá / định giá", "How should we price the new AI credits?", "Chung"], ["Easy", "usage", "n", "mức sử dụng", "Usage tripled after the launch.", "Chung"], ["Medium", "rate limit", "n", "giới hạn số request trong một khoảng thời gian", "We hit the API rate limit during the demo.", "Chung"], ["Medium", "quota", "n", "hạn mức", "Our daily quota resets at midnight Pacific time.", "Chung"], ["Medium", "cost per image", "n", "chi phí cho mỗi ảnh", "Cost per image dropped to four cents.", "Chung"], ["Medium", "scale to zero", "phr v", "tự giảm tài nguyên về 0 khi không dùng", "The endpoint scales to zero at night.", "Chung"], ["Hard", "unit economics", "n", "hiệu quả kinh tế trên mỗi đơn vị sản phẩm", "The unit economics only work below ten cents per image.", "Chung"], ["Hard", "margin", "n", "biên lợi nhuận", "Cheaper inference directly improves our margin.", "Chung"], ["Easy", "free tier", "n", "gói miễn phí", "The free tier is fine for testing, not for production.", "JD"], ["Medium", "cost-efficient", "adj", "tiết kiệm chi phí", "We need a cost-efficient data pipeline.", "JD"], ["Hard", "spot instance", "n", "máy ảo giá rẻ có thể bị thu hồi", "Batch jobs can run on spot instances.", "JD"]], "s": ["Usage tripled after the launch, which is great, but the GPU budget is now a concern.", "Right now the cost per image is about nine cents, and the unit economics only work if we stay below ten.", "Can we scale to zero at night, and can we cache repeat requests?", "Also, we hit the rate limit twice last week, so we need a fallback."], "sp": "Đề xuất cho PM 3 cách giảm chi phí mỗi ảnh và ước lượng tác động."}, {"t": "Data & fine-tuning", "wk": 2, "w": [["Easy", "dataset", "n", "bộ dữ liệu", "The dataset has ten thousand labelled images.", "Chung"], ["Easy", "label", "n/v", "nhãn / gán nhãn", "Who will label the new images?", "Chung"], ["Easy", "train", "v", "huấn luyện", "We trained the model for three epochs.", "Chung"], ["Easy", "version", "n", "phiên bản", "Which version of the dataset did you use?", "Chung"], ["Medium", "fine-tune", "v", "tinh chỉnh mô hình trên dữ liệu riêng", "We fine-tuned the model on our own product photos.", "Chung"], ["Medium", "overfitting", "n", "học vẹt (tốt trên dữ liệu train, kém trên dữ liệu mới)", "Validation loss went up: a clear sign of overfitting.", "Chung"], ["Medium", "annotation", "n", "việc chú thích/gán nhãn dữ liệu", "Annotation guidelines must be clear before we start.", "Chung"], ["Medium", "data drift", "n", "dữ liệu thực tế thay đổi so với lúc train", "Data drift appeared when a new brand joined.", "Chung"], ["Hard", "LoRA (low-rank adaptation)", "n", "kỹ thuật tinh chỉnh nhẹ chỉ học thêm vài ma trận nhỏ", "A LoRA lets us adapt the model without retraining everything.", "Chung"], ["Hard", "distillation", "n", "chưng cất: dùng mô hình lớn dạy mô hình nhỏ", "Distillation gave us a model that is five times cheaper.", "Chung"], ["Easy", "missing value", "n", "giá trị bị thiếu", "Ten percent of the rows had missing values.", "CV"], ["Medium", "outlier", "n", "giá trị ngoại lai", "We removed outliers before training.", "CV"], ["Hard", "imputation", "n", "điền giá trị thiếu", "We used median imputation for missing prices.", "CV"]], "s": ["Before we fine-tune anything, let's agree on the dataset.", "Who labels it, and what are the annotation guidelines?", "Last time we saw overfitting because one brand dominated the data, and then data drift when a new brand joined.", "A LoRA is a cheap first step, and if inference cost is still too high, we can look at distillation."], "sp": "PM hỏi: 'Có nên fine-tune model riêng không?' — trả lời theo hướng ưu/nhược và chi phí."}, {"t": "Computer vision basics", "wk": 3, "w": [["Easy", "pixel", "n", "điểm ảnh", "The logo is only a few pixels wide.", "Chung"], ["Easy", "resolution", "n", "độ phân giải", "Customers need at least 2K resolution.", "Chung"], ["Easy", "crop", "v/n", "cắt khung ảnh", "The style guide defines a tight crop for shoes.", "Chung"], ["Easy", "brightness", "n", "độ sáng", "Brightness varies between the two studios.", "Chung"], ["Medium", "segmentation", "n", "phân vùng ảnh (tách vật thể theo từng điểm ảnh)", "We use segmentation to cut out the garment.", "Chung"], ["Medium", "object detection", "n", "phát hiện vật thể", "Object detection finds the hanger in the photo.", "Chung"], ["Medium", "colour accuracy", "n", "độ chính xác màu", "Colour accuracy is the top complaint from customers.", "Chung"], ["Medium", "mask", "n", "mặt nạ (vùng ảnh được chọn)", "The mask covers only the upper body.", "Chung"], ["Hard", "artifact", "n", "lỗi/nhiễu hình do xử lý hoặc AI sinh ra", "Look closely at the hands: there are artifacts.", "Chung"], ["Hard", "perceptual quality", "n", "chất lượng cảm nhận bằng mắt người", "Pixel metrics look good, but perceptual quality is poor.", "Chung"], ["Easy", "OCR", "n", "nhận dạng ký tự quang học", "Our OCR model reached 90 percent accuracy.", "CV"], ["Medium", "bounding box", "n", "khung bao vật thể", "The detector returns a bounding box for each garment.", "CV"], ["Hard", "point cloud", "n", "đám mây điểm 3D", "LiDAR gives us a point cloud of the street.", "CV"]], "s": ["The top complaint from customers is colour accuracy, not resolution.", "When we crop the image or change the brightness, the colour shifts slightly.", "We use segmentation to create a mask of the garment and only check the pixels inside it.", "Also, the metrics can look fine while perceptual quality is poor, so please look for artifacts by eye as well."], "sp": "Giải thích cho PM cách bạn đo 'colour accuracy' của sản phẩm trong ảnh."}, {"t": "Diffusion & image generation", "wk": 3, "w": [["Easy", "noise", "n", "nhiễu", "The model starts from random noise.", "Chung"], ["Easy", "seed", "n", "hạt giống ngẫu nhiên (để tái tạo kết quả)", "Fix the seed so we can reproduce the image.", "Chung"], ["Easy", "style", "n", "phong cách", "Keep the style consistent across the collection.", "Chung"], ["Easy", "edit", "v/n", "chỉnh sửa", "We only edit the clothing, not the face.", "Chung"], ["Medium", "diffusion model", "n", "mô hình khuếch tán (sinh ảnh từ nhiễu)", "Most image generators today are diffusion models.", "Chung"], ["Medium", "denoising step", "n", "bước khử nhiễu", "Four denoising steps instead of twenty cut the time by 40 percent.", "Chung"], ["Medium", "upscale", "v", "tăng độ phân giải", "We generate at 1K and upscale to 2K.", "Chung"], ["Medium", "inpainting", "n", "vẽ lại một vùng ảnh", "Inpainting replaces only the masked area.", "Chung"], ["Hard", "quantization", "n", "lượng tử hoá (giảm độ chính xác số để nhẹ hơn)", "Quantization lets the model fit on a smaller GPU.", "Chung"], ["Hard", "conditioning", "n", "điều kiện hoá (đầu vào định hướng việc sinh ảnh)", "The product image is used as conditioning.", "Chung"], ["Easy", "checkpoint", "n", "bản lưu trọng số mô hình", "Load the best checkpoint from last night's training.", "CV"], ["Medium", "lipsync", "n", "khớp khẩu hình với âm thanh", "The lipsync model matched the mouth to new audio.", "CV"], ["Hard", "temporal consistency", "n", "tính nhất quán giữa các khung hình", "Video models struggle with temporal consistency.", "CV/Sản phẩm"]], "s": ["A diffusion model starts from noise and removes it step by step.", "Each denoising step costs GPU time, so we use four steps instead of twenty.", "The product image is the conditioning, and inpainting only changes the masked area, so the face stays the same.", "If you fix the seed, you can reproduce the image exactly.", "Then we upscale to 2K."], "sp": "Giải thích đơn giản cho PM: vì sao giảm số bước sinh ảnh thì nhanh hơn nhưng có thể giảm chất lượng."}, {"t": "Image quality control", "wk": 3, "w": [["Easy", "defect", "n", "lỗi, khuyết tật", "Every defect is logged with a screenshot.", "Chung"], ["Easy", "blurry", "adj", "bị mờ", "Blurry images are rejected automatically.", "Chung"], ["Easy", "check", "v/n", "kiểm tra", "The system checks the crop and the background.", "Chung"], ["Easy", "reject", "v", "loại, từ chối", "The art director rejected two images.", "Chung"], ["Medium", "quality control (QC)", "n", "kiểm soát chất lượng", "AI-generated images go through QC like any other image.", "Chung"], ["Medium", "pass rate", "n", "tỉ lệ đạt", "The first-time pass rate is 83 percent.", "Chung"], ["Medium", "false positive", "n", "báo lỗi nhầm (cảnh báo sai)", "Too many false positives and people stop trusting the tool.", "Chung"], ["Medium", "threshold", "n", "ngưỡng", "We set the threshold at seven out of ten.", "Chung"], ["Hard", "consistency", "n", "tính nhất quán", "Consistency across a collection matters more than one perfect shot.", "Chung"], ["Hard", "edge case", "n", "trường hợp hiếm, ngoài thông thường", "Transparent fabric is an edge case for the model.", "Chung"], ["Easy", "manual review", "n", "duyệt thủ công", "Low scores go to manual review.", "JD"], ["Medium", "confidence score", "n", "điểm tin cậy", "Only auto-approve when the confidence score is high.", "JD"], ["Hard", "precision-recall trade-off", "n", "đánh đổi giữa precision và recall", "A stricter threshold is a precision-recall trade-off.", "JD"]], "s": ["The automatic QC checks every image for defects: blurry areas, the wrong crop, a missing logo.", "If the score is below the threshold, we reject it and generate again.", "The first-time pass rate is eighty-three percent.", "But be careful with false positives: if the tool flags good images, people stop trusting it.", "And transparent fabric is still an edge case."], "sp": "PM lo ngại QC tự động báo sai nhiều. Thuyết phục PM bằng kế hoạch đo và giảm false positive."}, {"t": "GPU & model serving", "wk": 3, "w": [["Easy", "GPU", "n", "bộ xử lý đồ hoạ (chạy AI)", "One GPU produces about two images a minute.", "Chung"], ["Easy", "server", "n", "máy chủ", "The model runs on a separate server.", "Chung"], ["Easy", "deploy", "v", "triển khai", "We deploy the new model on Tuesday.", "Chung"], ["Easy", "batch", "n/v", "lô / xử lý theo lô", "Studio jobs run in batches overnight.", "Chung"], ["Medium", "VRAM", "n", "bộ nhớ của GPU", "The model needs 20 gigabytes of VRAM.", "Chung"], ["Medium", "cold start", "n", "khởi động nguội (lần chạy đầu chậm)", "The first request after a cold start takes a minute.", "Chung"], ["Medium", "autoscaling", "n", "tự động tăng/giảm tài nguyên", "Autoscaling adds GPUs when the queue grows.", "Chung"], ["Medium", "concurrency", "n", "số tác vụ chạy đồng thời", "Each GPU handles a concurrency of one.", "Chung"], ["Hard", "mixed precision", "n", "tính toán kết hợp độ chính xác số thấp và cao để nhanh hơn", "Mixed precision made inference 30 percent faster.", "Chung"], ["Hard", "model serving", "n", "hạ tầng phục vụ mô hình qua API", "Model serving is a separate service from the main API.", "Chung"], ["Easy", "hardware", "n", "phần cứng", "The model runs on modest hardware.", "CV"], ["Medium", "edge device", "n", "thiết bị biên (chạy AI tại chỗ)", "I deployed models on edge devices like the Jetson Nano.", "CV"], ["Hard", "half precision (FP16)", "n", "số thực 16-bit để chạy nhanh hơn", "Half precision cut inference time almost in half.", "CV"]], "s": ["Model serving is separate from the main API.", "Each GPU handles one job at a time, and one image takes about thirty seconds.", "Autoscaling adds more GPUs when the queue grows, but a cold start takes almost a minute, so we keep one warm during the day.", "Mixed precision and batching for studio jobs could give us another thirty percent."], "sp": "Ước lượng cho PM: muốn phục vụ 1.000 người thử đồ trong 5 phút thì cần bao nhiêu GPU, và cách giảm."}, {"t": "AWS", "wk": 3, "w": [["Easy", "cloud", "n", "đám mây (hạ tầng thuê ngoài)", "Everything runs in the cloud.", "Chung"], ["Easy", "bucket", "n", "kho lưu trữ (trên S3)", "Outputs go to a private bucket.", "Chung"], ["Easy", "region", "n", "vùng (trung tâm dữ liệu)", "EU customers need data in an EU region.", "Chung"], ["Easy", "instance", "n", "máy ảo", "We use one GPU instance for testing.", "Chung"], ["Medium", "S3", "n", "dịch vụ lưu trữ file của AWS", "Images are stored in S3 with presigned URLs.", "Chung"], ["Medium", "SQS queue", "n", "hàng đợi tin nhắn của AWS", "Each try-on is one message in an SQS queue.", "Chung"], ["Medium", "Lambda function", "n", "hàm chạy không cần máy chủ của AWS", "A Lambda function resizes the thumbnails.", "Chung"], ["Medium", "ECS container", "n", "container chạy trên dịch vụ ECS", "The API runs as an ECS container on Fargate.", "Chung"], ["Hard", "SageMaker endpoint", "n", "điểm truy cập phục vụ mô hình trên SageMaker", "An async SageMaker endpoint can scale to zero.", "Chung"], ["Hard", "Step Functions", "n", "dịch vụ điều phối quy trình nhiều bước của AWS", "Step Functions runs the studio batch with an approval step.", "Chung"], ["Easy", "container", "n", "container (gói ứng dụng chạy độc lập)", "Each service runs in its own container.", "CV"], ["Medium", "Docker image", "n", "ảnh Docker", "Build the Docker image in CI.", "CV"], ["Hard", "Kubernetes (EKS/GKE)", "n", "hệ thống điều phối container", "We deployed the agents on Kubernetes.", "CV"]], "s": ["Here's how it would look on AWS.", "The API runs as an ECS container.", "Each job is a message in an SQS queue, and the GPU work runs on an async SageMaker endpoint that can scale to zero.", "Results go to a private S3 bucket.", "For studio batches, Step Functions handles the flow and waits for a human approval.", "EU data stays in an EU region."], "sp": "Vẽ bằng lời cho PM kiến trúc demo của bạn khi đưa lên AWS."}, {"t": "Event-driven architecture", "wk": 3, "w": [["Easy", "queue", "n", "hàng đợi", "The queue absorbs traffic spikes.", "Chung"], ["Easy", "event", "n", "sự kiện", "An event is published when the image is ready.", "Chung"], ["Easy", "message", "n", "tin nhắn (trong hàng đợi)", "Each message contains the job ID.", "Chung"], ["Easy", "service", "n", "dịch vụ", "The QC service listens for new images.", "Chung"], ["Medium", "microservice", "n", "dịch vụ nhỏ độc lập", "We don't need ten microservices for this.", "Chung"], ["Medium", "retry", "v/n", "thử lại", "Failed jobs retry three times.", "Chung"], ["Medium", "idempotent", "adj", "chạy lại nhiều lần vẫn cho cùng kết quả", "The handler must be idempotent because messages can arrive twice.", "Chung"], ["Medium", "dead-letter queue (DLQ)", "n", "hàng đợi chứa tin nhắn lỗi", "After three failures, the job goes to the dead-letter queue.", "Chung"], ["Hard", "eventual consistency", "n", "nhất quán sau một khoảng thời gian", "The dashboard has eventual consistency: it updates within seconds.", "Chung"], ["Hard", "back-pressure", "n", "cơ chế giảm tốc khi hệ thống phía sau quá tải", "We need back-pressure so the GPUs aren't flooded.", "Chung"], ["Easy", "scale", "v", "mở rộng quy mô", "Will it scale to a million images a day?", "JD"], ["Medium", "data pipeline", "n", "luồng xử lý dữ liệu", "The data pipeline runs every hour.", "JD"], ["Hard", "workflow orchestrator (Airflow)", "n", "công cụ điều phối luồng dữ liệu", "Airflow is our workflow orchestrator.", "CV"]], "s": ["Why a queue?", "Because a try-on takes thirty seconds and traffic comes in spikes.", "The API publishes a message, and a worker picks it up.", "If it fails, it retries, and after three failures it goes to the dead-letter queue.", "The handler is idempotent, because a message can arrive twice.", "And the dashboard has eventual consistency: it catches up within seconds."], "sp": "PM hỏi: 'Sao không gọi thẳng GPU cho đơn giản?' — giải thích lợi ích của queue."}, {"t": "MLOps & reliability", "wk": 3, "w": [["Easy", "log", "n/v", "nhật ký hệ thống / ghi nhật ký", "Check the logs for the job ID.", "Chung"], ["Easy", "alert", "n", "cảnh báo", "We get an alert if the error rate goes above two percent.", "Chung"], ["Easy", "monitor", "v", "giám sát", "We monitor latency and cost per image.", "Chung"], ["Easy", "release", "n/v", "bản phát hành / phát hành", "The next release is on Wednesday.", "Chung"], ["Medium", "CI/CD", "n", "tích hợp và triển khai liên tục", "The CI/CD pipeline runs the eval before every deploy.", "Chung"], ["Medium", "rollback", "n/v", "quay về phiên bản trước", "If QC drops, we roll back within five minutes.", "Chung"], ["Medium", "observability", "n", "khả năng quan sát hệ thống (log, metric, trace)", "Good observability saved us during the incident.", "Chung"], ["Medium", "A/B test", "n", "thử nghiệm so sánh hai phiên bản", "We'll A/B test the new prompt with ten percent of users.", "Chung"], ["Hard", "canary release", "n", "phát hành thử cho một nhóm nhỏ trước", "Let's do a canary release to one studio first.", "Chung"], ["Hard", "SLA / SLO", "n", "cam kết / mục tiêu mức dịch vụ", "Our SLO is 99.5 percent of jobs done within two minutes.", "Chung"], ["Easy", "unit test", "n", "kiểm thử đơn vị", "Every function has a unit test.", "JD"], ["Medium", "version control (Git)", "n", "quản lý phiên bản mã", "Prompts are in version control too.", "JD"], ["Hard", "experiment tracking", "n", "theo dõi các lần thí nghiệm (MLflow, W&B)", "Experiment tracking shows which run was best.", "CV"]], "s": ["For the release on Wednesday, the CI/CD pipeline runs the eval first.", "We'll do a canary release to one studio and monitor latency, error rate and cost.", "If the QC pass rate drops, we roll back.", "Alerts go to the team channel.", "Our SLO is that ninety-nine point five percent of jobs finish within two minutes."], "sp": "Trình bày kế hoạch release một model mới cho PM: các bước, cách giám sát, khi nào rollback."}, {"t": "Agile basics", "wk": 4, "w": [["Easy", "sprint", "n", "chu kỳ làm việc ngắn (thường 2 tuần)", "This sprint we focus on the QC model.", "Chung"], ["Easy", "backlog", "n", "danh sách việc chờ làm", "Put it in the backlog for now.", "Chung"], ["Easy", "ticket", "n", "phiếu công việc (Jira...)", "Can you create a ticket for that bug?", "Chung"], ["Easy", "estimate", "v/n", "ước lượng", "How long do you estimate it will take?", "Chung"], ["Medium", "user story", "n", "mô tả nhu cầu dưới góc nhìn người dùng", "As a studio lead, I want to see failed images first.", "Chung"], ["Medium", "acceptance criteria", "n", "tiêu chí nghiệm thu", "What are the acceptance criteria for this ticket?", "Chung"], ["Medium", "story points", "n", "điểm ước lượng độ phức tạp", "The team gave it five story points.", "Chung"], ["Medium", "retrospective", "n", "buổi nhìn lại cuối sprint", "Let's discuss that in the retrospective.", "Chung"], ["Hard", "definition of done", "n", "định nghĩa thế nào là hoàn thành", "Our definition of done includes tests and an eval run.", "Chung"], ["Hard", "scope creep", "n", "phạm vi công việc phình dần ngoài kế hoạch", "Adding video now would be scope creep.", "Chung"], ["Easy", "deliverable", "n", "sản phẩm bàn giao", "The deliverable is a working API and a report.", "JD"], ["Medium", "technical debt", "n", "nợ kỹ thuật", "We took on technical debt to ship the demo.", "JD"], ["Hard", "refactor", "v", "tái cấu trúc mã", "Let's refactor the worker before adding video.", "JD"]], "s": ["Okay, sprint planning.", "The top of the backlog is the QC model.", "Here's the user story: as a studio lead, I want failed images flagged before the art director sees them.", "What are the acceptance criteria, and how many story points?", "Remember our definition of done includes an eval run.", "Adding video now would be scope creep, so let's keep it for the next sprint."], "sp": "Mô phỏng sprint planning: PM đưa user story, bạn hỏi acceptance criteria và ước lượng."}, {"t": "Planning & prioritising", "wk": 4, "w": [["Easy", "priority", "n", "mức ưu tiên", "What's the top priority this week?", "Chung"], ["Easy", "goal", "n", "mục tiêu", "The goal is a working demo by Friday.", "Chung"], ["Easy", "risk", "n", "rủi ro", "The biggest risk is GPU availability.", "Chung"], ["Easy", "launch", "n/v", "ra mắt", "We launch to all customers in March.", "Chung"], ["Medium", "roadmap", "n", "lộ trình sản phẩm", "This feature is on the Q2 roadmap.", "Chung"], ["Medium", "milestone", "n", "cột mốc", "The first milestone is an internal demo.", "Chung"], ["Medium", "MVP (minimum viable product)", "n", "sản phẩm khả dụng tối thiểu", "The MVP only supports tops, not shoes.", "Chung"], ["Medium", "dependency", "n", "sự phụ thuộc (vào việc/nhóm khác)", "We have a dependency on the platform team.", "Chung"], ["Hard", "must-have / nice-to-have", "n", "bắt buộc phải có / có thì tốt", "Batch export is a must-have; dark mode is a nice-to-have.", "Chung"], ["Hard", "de-scope", "v", "cắt bớt phạm vi", "If we're late, we de-scope the video part.", "Chung"], ["Easy", "research", "n/v", "nghiên cứu", "Give me two days of research before we decide.", "JD/CV"], ["Medium", "spike", "n", "đầu việc nghiên cứu ngắn trong agile", "Let's do a two-day spike on the new model.", "JD"], ["Hard", "state of the art (SOTA)", "n", "tốt nhất hiện nay", "The state of the art changes every few months.", "JD"]], "s": ["Let's look at the roadmap.", "The goal for this quarter is to launch automatic QC.", "The first milestone is an MVP that only handles tops.", "Our biggest risk is a dependency on the platform team for the new storage API.", "Batch export is a must-have, the dashboard is a nice-to-have, and if we fall behind, we de-scope the dashboard."], "sp": "PM đưa 5 yêu cầu nhưng chỉ đủ thời gian cho 2. Bạn đề xuất ưu tiên và giải thích vì sao."}, {"t": "Estimates & status updates", "wk": 4, "w": [["Easy", "on track", "adj", "đúng tiến độ", "Are we still on track for Friday?", "Chung"], ["Easy", "delay", "n/v", "sự chậm trễ / làm chậm", "There's a two-day delay on the GPU order.", "Chung"], ["Easy", "ETA", "n", "thời gian dự kiến hoàn thành", "What's the ETA on the new model?", "Chung"], ["Easy", "finish", "v", "hoàn thành", "I'll finish the tests by tomorrow.", "Chung"], ["Medium", "heads-up", "n", "báo trước (để người khác chuẩn bị)", "Just a heads-up: the API will be down tonight.", "Chung"], ["Medium", "slip", "v", "trượt, bị trễ (deadline)", "The release might slip by a week.", "Chung"], ["Medium", "buffer", "n", "thời gian dự phòng", "I added two days of buffer for testing.", "Chung"], ["Medium", "workaround", "n", "cách xử lý tạm thời", "There's a workaround until the fix is out.", "Chung"], ["Hard", "ballpark figure", "n", "con số ước lượng sơ bộ", "Just give me a ballpark figure, not an exact number.", "Chung"], ["Hard", "under-promise and over-deliver", "idiom", "hứa ít, làm nhiều hơn", "I'd rather under-promise and over-deliver.", "Chung"], ["Easy", "on hold", "adj", "tạm dừng", "The video feature is on hold.", "JD"], ["Medium", "capacity", "n", "năng lực/khả năng đảm nhận", "I don't have capacity for that this sprint.", "JD"], ["Hard", "level of effort", "n", "mức công sức ước tính", "What's the level of effort for the export feature?", "JD"]], "s": ["Quick status check.", "Are we on track?", "Give me a ballpark figure for the ETA.", "Just a heads-up from my side: the customer demo moved to next Tuesday.", "If the release might slip, tell me early, I really prefer that to a surprise.", "And if there's a workaround for the colour issue, we can ship with it and fix it properly later."], "sp": "Báo với PM rằng việc của bạn sẽ trễ 3 ngày: nói rõ lý do, tác động và phương án."}, {"t": "Demos & presenting results", "wk": 4, "w": [["Easy", "demo", "n/v", "bản trình diễn / trình diễn", "Can you demo it on Friday?", "Chung"], ["Easy", "slide", "n", "trang trình chiếu", "Put the numbers on one slide.", "Chung"], ["Easy", "chart", "n", "biểu đồ", "The chart shows latency per week.", "Chung"], ["Easy", "improve", "v", "cải thiện", "Did the new prompt improve the score?", "Chung"], ["Medium", "walk through", "phr v", "trình bày từng bước", "Let me walk you through the results.", "Chung"], ["Medium", "takeaway", "n", "điểm rút ra chính", "The key takeaway is that retries don't help much.", "Chung"], ["Medium", "highlight", "v", "nhấn mạnh", "I want to highlight one surprising result.", "Chung"], ["Medium", "proof of concept (PoC)", "n", "bản thử nghiệm chứng minh ý tưởng", "This is a proof of concept, not production code.", "Chung"], ["Hard", "caveat", "n", "lưu ý, điều kiện kèm theo", "One caveat: the sample is only twelve images.", "Chung"], ["Hard", "statistically significant", "adj", "có ý nghĩa thống kê", "The difference isn't statistically significant yet.", "Chung"], ["Easy", "paper", "n", "bài báo khoa học", "I co-authored eight papers.", "CV"], ["Medium", "peer-reviewed", "adj", "được bình duyệt", "They were published in peer-reviewed journals.", "CV"], ["Hard", "ablation study", "n", "thí nghiệm bỏ bớt thành phần để đo tác dụng", "An ablation study showed the reranker added five points.", "CV"]], "s": ["Let me walk you through the results.", "This is a proof of concept, so one caveat: the sample is small, only twelve pairs, and the difference isn't statistically significant yet.", "The key takeaway is that the computed score catches failures the judge missed.", "I also want to highlight one surprise: retrying didn't rescue any failed image."], "sp": "Demo kết quả eval của bạn cho PM trong 3 phút, nêu rõ caveat và takeaway."}, {"t": "Feedback & disagreement (Danish style)", "wk": 4, "w": [["Easy", "feedback", "n", "góp ý", "Any feedback on the design?", "Chung"], ["Easy", "opinion", "n", "ý kiến", "In my opinion, we should test it first.", "Chung"], ["Easy", "concern", "n", "mối lo ngại", "My main concern is the cost.", "Chung"], ["Easy", "honest", "adj", "thẳng thắn, trung thực", "To be honest, it isn't ready yet.", "Chung"], ["Medium", "constructive", "adj", "mang tính xây dựng", "Thanks, that's very constructive feedback.", "Chung"], ["Medium", "straightforward", "adj", "thẳng thắn; đơn giản", "Danish colleagues are usually very straightforward.", "Chung"], ["Medium", "I see your point", "phrase", "tôi hiểu ý anh/chị", "I see your point, but the data says otherwise.", "Chung"], ["Medium", "to be fair", "phrase", "công bằng mà nói", "To be fair, the old model was cheaper.", "Chung"], ["Hard", "devil's advocate", "n", "người cố tình phản biện để thử ý tưởng", "Let me play devil's advocate for a second.", "Chung"], ["Hard", "understatement", "n", "cách nói giảm (vd 'not bad' = rất tốt)", "When a Dane says 'not bad', it's an understatement: it's good.", "Chung"], ["Easy", "secure", "adj/v", "an toàn / bảo vệ", "Keep the API keys secure.", "JD"], ["Medium", "security review", "n", "rà soát bảo mật", "The new connector needs a security review.", "JD"], ["Hard", "least privilege", "n", "nguyên tắc quyền tối thiểu", "The worker follows least privilege: it can only read one bucket.", "JD"]], "s": ["I'll be straightforward with you, that's how we work here.", "The demo is not bad, and honestly, that means it's good.", "But I have one concern: the cost.", "Let me play devil's advocate: why not use an external API?", "I see your point about quality, but to be fair, the API is much faster to ship.", "Please push back if you disagree."], "sp": "PM người Đan Mạch phản biện thẳng thiết kế của bạn. Bạn bảo vệ quan điểm lịch sự nhưng rõ ràng."}, {"t": "Incidents & bugs", "wk": 4, "w": [["Easy", "bug", "n", "lỗi phần mềm", "We found a bug in the export.", "Chung"], ["Easy", "fix", "v/n", "sửa / bản sửa", "The fix is already in review.", "Chung"], ["Easy", "crash", "n/v", "sập", "The worker crashed during the night.", "Chung"], ["Easy", "error", "n", "lỗi", "Users see an error after uploading.", "Chung"], ["Medium", "root cause", "n", "nguyên nhân gốc", "We haven't found the root cause yet.", "Chung"], ["Medium", "incident", "n", "sự cố", "We had an incident this morning: QC was down for an hour.", "Chung"], ["Medium", "hotfix", "n", "bản sửa khẩn cấp", "We'll ship a hotfix tonight.", "Chung"], ["Medium", "reproduce", "v", "tái hiện lỗi", "I can't reproduce it on my machine.", "Chung"], ["Hard", "post-mortem", "n", "buổi phân tích sau sự cố", "We'll write a post-mortem without blaming anyone.", "Chung"], ["Hard", "mitigate", "v", "giảm thiểu (tác động)", "To mitigate the impact, we sent images to manual review.", "Chung"], ["Easy", "downtime", "n", "thời gian ngừng hoạt động", "We had ten minutes of downtime.", "JD"], ["Medium", "failover", "n", "chuyển sang hệ dự phòng", "Failover to the backup model worked.", "JD"], ["Hard", "single point of failure", "n", "điểm hỏng duy nhất làm sập cả hệ thống", "One GPU server is a single point of failure.", "JD"]], "s": ["We had an incident this morning.", "The QC service crashed and users saw an error for about an hour.", "To mitigate it, we sent all images to manual review.", "We can reproduce the bug now, and the root cause is a timeout when the model is overloaded.", "A hotfix goes out tonight, and we'll write a post-mortem tomorrow.", "No blame, just lessons."], "sp": "Báo cáo sự cố cho PM: chuyện gì xảy ra, ảnh hưởng, đã xử lý tạm ra sao, bước tiếp theo."}, {"t": "Privacy, security & compliance", "wk": 4, "w": [["Easy", "privacy", "n", "quyền riêng tư", "Privacy is a top concern for EU customers.", "Chung"], ["Easy", "consent", "n", "sự đồng ý", "We ask for consent before storing the photo.", "Chung"], ["Easy", "delete", "v", "xoá", "Photos are deleted after 24 hours.", "Chung"], ["Easy", "access", "n/v", "quyền truy cập / truy cập", "Only the worker has access to the bucket.", "Chung"], ["Medium", "GDPR", "n", "quy định bảo vệ dữ liệu cá nhân của EU", "Under GDPR, users can ask us to delete their data.", "Chung"], ["Medium", "personal data", "n", "dữ liệu cá nhân", "A face photo is personal data.", "Chung"], ["Medium", "encryption", "n", "mã hoá", "All files use encryption at rest.", "Chung"], ["Medium", "data retention", "n", "thời gian/chính sách lưu giữ dữ liệu", "Our data retention policy is 30 days for logs.", "Chung"], ["Hard", "EU AI Act", "n", "Đạo luật AI của Liên minh châu Âu", "The EU AI Act requires labelling AI-generated content.", "Chung"], ["Hard", "content provenance (C2PA)", "n", "nguồn gốc nội dung (chuẩn C2PA)", "We add C2PA credentials so customers can prove an image is AI-generated.", "Chung"], ["Easy", "anonymise", "v", "ẩn danh hoá", "We anonymise the logs before analysis.", "JD"], ["Medium", "SOC 2", "n", "chuẩn kiểm toán bảo mật SOC 2", "Enterprise customers ask for our SOC 2 report.", "Sản phẩm"], ["Hard", "data residency", "n", "yêu cầu dữ liệu nằm ở một quốc gia/khu vực", "Data residency rules keep EU photos in the EU.", "JD"]], "s": ["Before we launch in Europe, legal wants three things.", "First, consent: users agree before we store a photo, because a face is personal data under GDPR.", "Second, data retention: photos are deleted after twenty-four hours and everything uses encryption.", "Third, the EU AI Act: generated images must be labelled, so we'll add C2PA content credentials."], "sp": "PM hỏi: 'Khách EU lo về ảnh người dùng, mình trả lời họ thế nào?'"}, {"t": "Remote work & Danish culture", "wk": 4, "w": [["Easy", "time zone", "n", "múi giờ", "Denmark is five or six hours behind Vietnam.", "Chung"], ["Easy", "schedule", "v/n", "lên lịch / lịch", "Let's schedule the call for 3 pm your time.", "Chung"], ["Easy", "reschedule", "v", "dời lịch", "Can we reschedule to tomorrow morning?", "Chung"], ["Easy", "day off", "n", "ngày nghỉ", "I'm taking a day off on Friday.", "Chung"], ["Medium", "async", "adj", "bất đồng bộ (không cần cùng lúc)", "Let's handle this async in the ticket.", "Chung"], ["Medium", "flat hierarchy", "n", "cơ cấu tổ chức phẳng", "With a flat hierarchy, you can talk to anyone directly.", "Chung"], ["Medium", "work-life balance", "n", "cân bằng công việc và cuộc sống", "Nobody expects replies after 5 pm: work-life balance matters here.", "Chung"], ["Medium", "ownership", "n", "tinh thần làm chủ công việc", "We expect ownership: if you start it, you drive it.", "Chung"], ["Hard", "hygge", "n", "sự ấm cúng, thoải mái (văn hoá Đan Mạch)", "Friday cake is a bit of hygge in the office.", "Chung"], ["Hard", "Law of Jante", "n", "chuẩn mực Đan Mạch: không khoe khoang, đề cao tập thể", "Because of the Law of Jante, people rarely brag about their work.", "Chung"], ["Easy", "documentation", "n", "tài liệu", "Please update the documentation with the new endpoint.", "JD"], ["Medium", "README", "n", "file hướng dẫn trong repo", "The README explains how to run it locally.", "JD"], ["Hard", "architecture decision record (ADR)", "n", "bản ghi quyết định kiến trúc", "Write an ADR so we remember why we chose SQS.", "JD"]], "s": ["Some practical things.", "We're in different time zones, so we schedule calls in your afternoon and handle the rest async in the tickets.", "We have a flat hierarchy, so talk to anyone directly.", "We expect ownership: if you start something, you drive it.", "And work-life balance is real here: nobody expects replies after five.", "Oh, and Friday cake is mandatory."], "sp": "Small talk đầu buổi họp: hỏi han, kể về cuối tuần, hỏi về văn hoá làm việc ở Đan Mạch."}, {"t": "Proposals & review", "wk": 4, "w": [["Easy", "idea", "n", "ý tưởng", "I have an idea for the QC step.", "Chung"], ["Easy", "option", "n", "phương án", "We have three options.", "Chung"], ["Easy", "benefit", "n", "lợi ích", "The main benefit is fewer manual checks.", "Chung"], ["Easy", "improvement", "n", "sự cải tiến", "Even a small improvement saves hours every week.", "Chung"], ["Medium", "proposal", "n", "đề xuất", "I'll write a one-page proposal.", "Chung"], ["Medium", "pros and cons", "n", "ưu và nhược điểm", "Let's list the pros and cons of each option.", "Chung"], ["Medium", "impact", "n", "tác động", "What's the impact on turnaround time?", "Chung"], ["Medium", "feasibility", "n", "tính khả thi", "First we need a feasibility study.", "Chung"], ["Hard", "return on investment (ROI)", "n", "lợi tức đầu tư", "The ROI is clear if we save one retoucher per studio.", "Chung"], ["Hard", "buy-in", "n", "sự ủng hộ, đồng thuận (của các bên)", "We need buy-in from the studio leads before we build.", "Chung"], ["Easy", "solution", "n", "giải pháp", "We need a solution that studios can actually use.", "JD"], ["Medium", "business value", "n", "giá trị kinh doanh", "Start with the business value, then the model.", "JD"], ["Hard", "build vs buy", "n", "tự xây hay mua/thuê dịch vụ", "For OCR it was build vs buy, and we built.", "JD/CV"]], "s": ["I like the idea, so let's make it concrete.", "Write a one-page proposal with three options and the pros and cons of each.", "I need the impact on turnaround time and a rough ROI.", "Before we build anything big, run a small feasibility test with one studio.", "And talk to the studio leads early, because without their buy-in, nobody will use it."], "sp": "Ôn tổng: trình bày một đề xuất AI cho Creative Force trong 5 phút (vấn đề, phương án, ROI, kế hoạch)."}], "weeks": {"1": ["Product, studio & meetings", "Video giới thiệu Creative Force (Daniel, Chief Evangelist): https://www.youtube.com/watch?v=Qay_WqL5EAo — chép chính tả từng đoạn, so với transcript."], "2": ["AI engineering core", "Webinar/talk của Creative Force trên YouTube (kênh Creative Force), talk AI ngắn (TED, các kênh kỹ thuật) tốc độ 1×."], "3": ["Computer vision, GenAI & infrastructure", "Talk về diffusion / AWS (AWS re:Invent, các kênh kỹ thuật); phát biểu của người Đan Mạch nói tiếng Anh (Margrethe Vestager, Bjarke Ingels)."], "4": ["Project communication", "Họp mẫu trên YouTube ('sprint planning example', 'agile standup meeting'); ghi âm cuộc họp thật (xin phép) và chép lại đoạn khó; nghe ở tốc độ 1.1–1.25×."]}, "pron": [["Kubernetes", "koo-ber-NET-eez", "Hay nói tắt 'K8s' = 'kay-eights'", "We deploy everything on Kubernetes."], ["PyTorch", "PIE-torch", "'Py' đọc như 'pie'", "The model is written in PyTorch."], ["scikit-learn", "SY-kit learn", "'sci' đọc 'sy', không phải 'ski'", "We used scikit-learn for the baseline."], ["Azure", "AZH-er", "Không đọc 'a-zua'", "Some customers run on Azure."], ["SQL", "SEE-kwel / ess-kyoo-ell", "Hai cách đều phổ biến", "Can you write a SQL query for that?"], ["cache", "cash", "Đọc giống 'cash' (tiền mặt)", "Check the cache first."], ["JSON", "JAY-son", "Như tên 'Jason'", "The model returns JSON."], ["YAML", "YAM-ul", "Vần với 'camel'", "The config is in a YAML file."], ["async", "AY-sink", "Âm đầu 'ay'", "Make that call async."], ["GPU", "jee-pee-YOU", "", "We need another GPU."], ["LLM", "ell-ell-EM", "", "Which LLM are we using?"], ["VLM", "vee-ell-EM", "", "A VLM checks the image."], ["LoRA", "LOR-uh", "Như tên 'Laura'", "We trained a LoRA on our photos."], ["Milvus", "MIL-vus", "", "Vectors are stored in Milvus."], ["FastAPI", "fast-ay-pee-EYE", "", "The service uses FastAPI."], ["Jupyter", "JOO-pi-ter", "Như hành tinh 'Jupiter'", "I tested it in a Jupyter notebook."], ["Nginx", "engine-X", "Không đọc 'n-gin-x'", "Nginx sits in front of the API."], ["Linux", "LIN-ux", "'Li' ngắn như 'lin'", "The servers run Linux."], ["GIF", "gif / jif", "Hai cách, cả hai đều được chấp nhận", "Send me a GIF of the demo."], ["SaaS", "sass", "Đọc như 'sass'", "We are a SaaS company."], ["S3", "ess-THREE", "", "Upload it to S3."], ["SQS", "ess-kyoo-ESS", "", "Put the job on SQS."], ["ECS / EKS", "ee-see-ESS / ee-kay-ESS", "Dễ nghe nhầm, chú ý âm giữa", "The API runs on ECS."], ["SageMaker", "SAGE-may-ker", "", "Host the model on SageMaker."], ["Gemini", "JEM-in-eye", "Thường nghe 'JEM-in-ee' cũng có", "We call Gemini for chat."], ["Claude", "klawd", "Một âm tiết, giống 'clawed'", "I wrote it with Claude Code."], ["LangGraph", "LANG-graf", "", "The agent is built with LangGraph."], ["CUDA", "KOO-duh", "", "Check the CUDA version."], ["ComfyUI", "COM-fee you-eye", "", "The workflow runs in ComfyUI."], ["C2PA", "see-two-pee-AY", "", "Images carry C2PA credentials."]]};